const rows = $input.all().map(i => i.json);

const config = {};

for (const row of rows) {
  const key = String(row.campo || '').trim();
  const value = row.valor ?? '';

  if (key) config[key] = value;
}

function splitList(value) {
  return String(value || '')
    .split(',')
    .map(v => v.trim())
    .filter(Boolean);
}

const feedUrlAuto =
  'https://contrataciondelsectorpublico.gob.es/sindicacion/sindicacion_643/licitacionesPerfilesContratanteCompleto3.atom';

return [{
  json: {
    feed_url: config.feed_url && String(config.feed_url).trim()
      ? String(config.feed_url).trim()
      : feedUrlAuto,

    keywords: splitList(config.keywords),
    keywords_fuertes: splitList(config.keywords_fuertes),
    exclude_keywords: splitList(config.exclude_keywords),
    provincias: splitList(config.provincia),
    cpvs: splitList(config.cpv),

    importe_min: Number(config.importe_min || 0),
    email_destino: String(config.email_destino || '').trim(),
    max_resultados: Number(config.max_resultados || 25),
    solo_abiertas: String(config.solo_abiertas || '').toLowerCase() === 'sí',
    frecuencia: String(config.frecuencia || 'diaria').trim()
  }
}];

const config = $('Normalizar configuración').first().json;
const allInputs = $input.all();

const keywords = config.keywords || [];
const keywordsFuertes = config.keywords_fuertes || [];
const excludeKeywords = config.exclude_keywords || [];
const provincias = config.provincias || [];
const cpvs = config.cpvs || [];
const maxResultados = Number(config.max_resultados || 100);

function textOf(value) {
  if (!value) return '';
  if (typeof value === 'string') return value;
  if (value._) return value._;
  if (value['#text']) return value['#text'];
  return JSON.stringify(value);
}

function normalizeText(value) {
  return String(value || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function normalizeCpv(value) {
  return String(value || '').replace(/[^0-9]/g, '');
}

function getEntries(xml) {
  const feed = xml.feed || xml;
  let entries = feed.entry || [];
  if (!entries) return [];
  if (!Array.isArray(entries)) entries = [entries];
  return entries;
}

function countMatches(texto, lista) {
  return lista.filter(k => texto.includes(normalizeText(k))).length;
}

const resultados = [];

for (const input of allInputs) {
  const entries = getEntries(input.json);

  for (const entry of entries) {
    const title = textOf(entry.title);
    const summary = textOf(entry.summary);
    const id = textOf(entry.id);
    const updated = textOf(entry.updated);

    let link = '';
    if (Array.isArray(entry.link)) {
      const alt = entry.link.find(l => l.rel === 'alternate') || entry.link[0];
      link = alt?.href || '';
    } else if (entry.link) {
      link = entry.link.href || '';
    }

    const texto = normalizeText(JSON.stringify(entry));
    const textoCpv = normalizeCpv(JSON.stringify(entry));

    const matchesNormales = countMatches(texto, keywords);
    const matchesFuertes = countMatches(texto, keywordsFuertes);

    const pasaKeyword =
      matchesFuertes >= 1 ||
      matchesNormales >= 2 ||
      keywords.length === 0;

    const pasaExclusion =
      excludeKeywords.length === 0 ||
      countMatches(texto, excludeKeywords) === 0;

    const pasaProvincia =
      provincias.length === 0 ||
      provincias.some(p => texto.includes(normalizeText(p)));

    const pasaCpv =
      cpvs.length === 0 ||
      cpvs.some(cpv => {
        const cpvNormalizado = normalizeCpv(cpv);
        return cpvNormalizado && textoCpv.includes(cpvNormalizado);
      });

    if (pasaKeyword && pasaExclusion && pasaProvincia && pasaCpv) {
      resultados.push({
        id,
        title,
        summary,
        updated,
        link,
        matches_normales: matchesNormales,
        matches_fuertes: matchesFuertes,
      });
    }
  }
}

const unicos = Array.from(
  new Map(resultados.map(r => [r.id || r.link || r.title, r])).values()
);

const salida = unicos.slice(0, maxResultados);

if (salida.length === 0) {
  return [{
    json: {
      id: 'sin-resultados',
      title: 'No se encontraron licitaciones con los filtros actuales',
      summary: 'Prueba ampliando keywords, quitando CPV o ajustando keywords_fuertes.',
      updated: new Date().toISOString(),
      link: '',
    }
  }];
}

return salida.map(r => ({ json: r }));

const items = $input.all();
const config = $('Normalizar configuración').first().json;

const rows = items.map((item, index) => {
  const r = item.json;
  return `
    <tr>
      <td>${index + 1}</td>
      <td><strong>${r.title || ''}</strong><br>${r.summary || ''}</td>
      <td><a href="${r.link || '#'}">Ver licitación</a></td>
      <td>${r.updated || ''}</td>
    </tr>
  `;
}).join('');

const html = `
<h2>Nuevas licitaciones encontradas</h2>
<p>Se han encontrado <strong>${items.length}</strong> licitaciones.</p>

<table border="1" cellpadding="8" cellspacing="0">
  <thead>
    <tr>
      <th>#</th>
      <th>Licitación</th>
      <th>Enlace</th>
      <th>Fecha</th>
    </tr>
  </thead>
  <tbody>
    ${rows}
  </tbody>
</table>
`;

return [{
  json: {
    email_destino: config.email_destino,
    subject: `Alertas licitaciones: ${items.length} resultados`,
    html,
  }
}];

const nuevas = $('Filtrar licitaciones').all();
const enviadas = $input.all();

const idsEnviados = new Set(
  enviadas
    .map(i => i.json.id_licitacion)
    .filter(Boolean)
);

const resultado = nuevas.filter(item => {
  const id = item.json.id;
  return id && !idsEnviados.has(id);
});

return resultado;

const config = $('Normalizar configuración').first().json;
const xml = $input.first().json;

const feed = xml.feed || xml;

function arr(v) {
  if (!v) return [];
  return Array.isArray(v) ? v : [v];
}

function getHref(link) {
  if (!link) return '';
  return link.href || link['@_href'] || link.$?.href || '';
}

const links = [
  ...arr(feed.link),
  ...arr(feed.entry).flatMap(e => arr(e.link))
];

let candidates = links
  .map(getHref)
  .filter(Boolean)
  .filter(h => /licitacionesPerfilesContratanteCompleto3_\d{8}_\d{6}\.atom/i.test(h));

candidates = [...new Set(candidates)];

if (candidates.length === 0) {
  throw new Error('No encontré enlaces .atom diarios dentro del índice. Revisa que feed_url apunte al .atom general, no a un ZIP ni a un .atom diario fijo.');
}

function score(url) {
  const m = url.match(/_(\d{8})_(\d{6})\.atom/i);
  return m ? `${m[1]}${m[2]}` : '';
}

candidates.sort((a, b) => score(b).localeCompare(score(a)));

let latest = candidates[0];

if (!latest.startsWith('http')) {
  latest = `https://contrataciondelsectorpublico.gob.es/sindicacion/sindicacion_643/${latest.replace(/^\/+/, '')}`;
}

return [{
  json: {
    ...config,
    feed_url_indice: config.feed_url,
    feed_url: latest,
    feed_atom_diario_detectado: latest,
    atom_candidates_found: candidates.length,
  }
}];

